const $=s=>document.querySelector(s), money=n=>Number(n||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}), num=n=>Number(n||0).toLocaleString('pt-BR',{maximumFractionDigits:1}), today=()=>new Date().toLocaleDateString('en-CA',{timeZone:'America/Sao_Paulo'}), uid=()=>crypto.randomUUID(), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=JSON.parse(localStorage.getItem('rotago-v1'))}catch{}state=state||{plan:{start:today(),end:today(),km:150,eff:10,price:6.19,off:[],dates:'',initial:0},bills:[],reserves:[],routes:[],theme:'light'};let tab='route',day=today(),period='week',reportDay=today();
function save(){try{localStorage.setItem('rotago-v1',JSON.stringify(state))}catch{toast('Não foi possível salvar. Exporte um backup.')}}
function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3500)}
function dateObj(d){return new Date(d+'T12:00:00')}function dates(a,b){let arr=[],d=dateObj(a);for(let i=0;d<=dateObj(b)&&i<3660;i++,d.setDate(d.getDate()+1))arr.push(d.toLocaleDateString('en-CA'));return arr}
function workDays(){let p=state.plan;return dates(p.start,p.end).filter(d=>!p.off.includes(dateObj(d).getDay())&&!p.dates.split(',').map(x=>x.trim()).includes(d))}
function fuel(r){return r.km/r.eff*r.price}function reserved(r){return Object.values(r.reserves||{}).reduce((a,b)=>a+Number(b),0)}function extras(r){return (r.expenses||[]).reduce((s,e)=>s+Number(e.amount),0)}function net(r){return r.gross-fuel(r)-reserved(r)-extras(r)}function hours(r){return (new Date(r.end)-new Date(r.start))/36e5}
function planning(asOf=today(),beforeDay=false){let p=state.plan,days=workDays(),remainingDays=days.filter(d=>d>=asOf),bills=state.bills.filter(b=>b.due<=p.end),total=bills.filter(b=>!b.paid).reduce((a,b)=>a+b.amount,0),paid=bills.filter(b=>b.paid).reduce((a,b)=>a+b.amount,0),routeCredit=state.routes.filter(r=>r.date>=p.start&&r.date<=p.end&&(beforeDay?r.date<asOf:r.date<=asOf)).reduce((a,r)=>a+net(r),0),separated=Number(p.initial)+routeCredit-paid,dailyReserve=state.reserves.reduce((a,b)=>a+b.daily,0),base=Math.max(0,total-separated),daily=remainingDays.length?base/remainingDays.length:0,gas=p.km/p.eff*p.price;return {days,remainingDays,total,base,daily,gas,dailyReserve,routeCredit,separated,paid,gross:daily+gas+dailyReserve}}
function target(d){let p=planning(d,true);return p.days.includes(d)?p.gross:0}function totals(rs){return rs.reduce((a,r)=>({gross:a.gross+r.gross,fuel:a.fuel+fuel(r),reserve:a.reserve+reserved(r),extras:a.extras+extras(r),net:a.net+net(r),km:a.km+r.km,hours:a.hours+hours(r)}),{gross:0,fuel:0,reserve:0,extras:0,net:0,km:0,hours:0})}
function stat(label,value,sub,icon,green=false){return `<div class="stat ${green?'green':''}"><div class="label">${label}<i>${icon}</i></div><strong>${value}</strong><small>${sub}</small></div>`}
function stats(t){return `<div class="stats">${stat('Faturamento bruto',money(t.gross),`${num(t.km)} km percorridos`,'↗')}${stat('Disponível para contas',money(t.net),'Após combustível, reservas e gastos','◈',true)}${stat('Ganho médio / hora',money(t.hours?t.gross/t.hours:0),`${num(t.hours)} horas na direção · bruto`,'◷')}${stat('Ganho médio / km',money(t.km?t.gross/t.km:0),'Recebido por quilômetro · bruto','⌁')}</div>`}
function allocation(t){let colors=['#1679f9','#16bedf','#f2b754','#e48880'];return `<div class="panel"><div class="panelhead"><div><h3>Seu dinheiro, bem dividido</h3><p>Veja para onde vai cada conquista</p></div><span>◉</span></div><div class="allocation"><div class="barstack">${[Math.max(0,t.net),t.fuel,t.reserve,t.extras].map((v,i)=>`<i style="width:${t.gross>0?Math.max(0,v/t.gross*100):0}%;background:${colors[i]}"></i>`).join('')}</div>${[['Para as contas',t.net],['Combustível',t.fuel],['Suas reservas',t.reserve],['Outros gastos',t.extras]].map((x,i)=>`<div class="legend"><span><i class="dot" style="background:${colors[i]}"></i>${x[0]}</span><b>${money(x[1])}</b></div>`).join('')}<div class="tip"><b>↗ Seu futuro também vai junto.</b><br>Separe um pouco a cada rota. Suas reservas crescem no seu ritmo.</div></div></div>`}
function routeTable(rs){return rs.length?`<div class="tablewrap"><table><thead><tr><th>PLATAFORMA / HORÁRIO</th><th>TRAJETO</th><th>RECEBIDO</th><th>PARA CONTAS</th><th></th></tr></thead><tbody>${rs.slice().sort((a,b)=>b.start.localeCompare(a.start)).map(r=>`<tr><td><span class="platform ${r.platform}">${r.platform==='Shopee'?'S':r.platform==='Uber'?'U':'99'}</span>${esc(r.platform)}<small>${dateObj(r.date).toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit'})} · ${r.start.slice(11,16)} — ${r.end.slice(11,16)}</small></td><td>${num(r.km)} km<small>${num(hours(r))} h · ${money(fuel(r))} combustível</small></td><td><b>${money(r.gross)}</b><small>${money(reserved(r))} reservas · ${money(extras(r))} gastos</small></td><td style="color:var(--green)"><b>${money(net(r))}</b><small>Meta do dia: ${money(r.targetSnapshot||0)}</small></td><td><button class="textbtn" onclick="routeForm('${r.id}')" aria-label="Editar rota">✎</button><button class="danger" onclick="remove('routes','${r.id}')" aria-label="Excluir rota">×</button></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><div class="emptyicon">⌁</div><strong>Sua próxima conquista começa aqui</strong>Registre uma rota para acompanhar seus resultados.<br><button class="secondary" onclick="routeForm()">＋ Registrar primeira rota</button></div>`}
function render(){document.body.classList.toggle('dark',state.theme==='dark');$('#theme').textContent=state.theme==='dark'?'☀':'☾';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));let names={route:'Rota / Meta',plan:'Planejamento',reports:'Relatórios'};$('#crumb').textContent=names[tab];$('#heading').innerHTML={route:'Seu dia na direção certa<span>.</span>',plan:'O amanhã começa no plano<span>.</span>',reports:'Cada quilômetro conta<span>.</span>'}[tab];$('#subtitle').textContent={route:'Acompanhe sua meta, registre suas rotas e veja seu dinheiro render.',plan:'Organize suas contas e descubra quanto precisa fazer por dia.',reports:'Transforme suas rotas em uma visão clara dos seus resultados.'}[tab];$('#topaction').textContent=tab==='plan'?'＋ Nova conta':'＋ Nova rota';if(tab==='route')renderRoute();if(tab==='plan')renderPlan();if(tab==='reports')renderReports()}
function renderRoute(){let rs=state.routes.filter(r=>r.date===day),t=totals(rs),p=planning(day,true),goal=target(day),pct=goal?Math.min(100,t.gross/goal*100):0,remaining=Math.max(0,goal-t.gross);$('#app').innerHTML=`<div class="datebar"><strong>◷ ${dateObj(day).toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long'})}</strong><input aria-label="Dia das rotas" type="date" id="routeDay" value="${day}"></div><div class="hero"><div><small>↗ SUA META DO DIA <span class="chip">${goal?'Planejamento conectado':'Sem meta neste dia'}</span></small><h2>${money(goal)}</h2><p>${goal?`Faltam <b>${money(remaining)}</b> para alcançar sua meta`:'Cadastre seu planejamento ou confira os dias de folga.'}</p><div class="progress"><i style="width:${pct}%"></i></div><div class="progresslabels"><span>${money(t.gross)} conquistados</span><span>${num(pct)}% da meta</span></div></div><div class="heroright"><div class="targetrow"><span>◈ Para pagar suas contas</span><b>${money(goal?p.daily:0)}</b></div><div class="targetrow"><span>⌁ Combustível previsto</span><b>${money(goal?p.gas:0)}</b></div><div class="targetrow"><span>◇ Reservas do dia</span><b>${money(goal?p.dailyReserve:0)}</b></div><div class="targetrow"><span>${t.gross>=goal&&goal?'✓ Além da meta':'◷ Dias de trabalho no plano'}</span><b>${t.gross>=goal&&goal?money(t.gross-goal):p.days.length+' dias'}</b></div></div></div>${stats(t)}<div class="grid"><div class="panel"><div class="panelhead"><div><h3>Suas rotas do dia</h3><p>Cada saída registrada, cada resultado na mão</p></div><span class="count">${rs.length} rotas</span></div>${routeTable(rs)}</div>${allocation(t)}</div><div class="bottomnote"><span style="color:var(--blue);font-size:20px">✧</span><span><b>Seu planejamento guia o caminho.</b> A meta inclui contas, combustível previsto e reservas. O resultado desconta combustível, reservas e outros gastos de cada rota.</span><button class="textbtn" onclick="switchTab('plan')">Ver plano →</button></div>`;$('#routeDay').onchange=e=>{day=e.target.value||today();render()}}
function field(label,name,type,value,extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value??'')}" ${extra}></label>`}function openModal(title,html,handler){$('#modaltitle').textContent=title;$('#form').innerHTML=html+`<div class="formactions"><button type="button" class="secondary" onclick="$('#modal').close()">Cancelar</button><button class="primary" type="submit">Salvar</button></div>`;$('#form').onsubmit=e=>{e.preventDefault();try{handler(new FormData(e.target))}catch(err){toast(err.message)}};$('#modal').showModal()}
function routeForm(id){let r=state.routes.find(r=>r.id===id),p=state.plan;openModal(r?'Editar rota':'Registrar nova rota',`<div class="fields">${field('Data da rota','date','date',r?.date||day,'required')}<label class="field">Plataforma<select name="platform">${['99','Uber','Shopee'].map(v=>`<option ${r?.platform===v?'selected':''}>${v}</option>`).join('')}</select></label>${field('Início','start','time',r?.start.slice(11,16)||'08:00','required')}${field('Fim','end','time',r?.end.slice(11,16)||'12:00','required')}<label class="field full">Como deseja informar os quilômetros?<select name="mode" id="kmMode"><option value="trip" ${r?.mode!=='odo'?'selected':''}>Quilometragem rodada (contador de viagem)</option><option value="odo" ${r?.mode==='odo'?'selected':''}>Hodômetro: KM inicial e KM final</option></select></label><div class="full fields" id="kmFields"></div>${field('Valor recebido (R$)','gross','number',r?.gross??'','min="0" step="0.01" required')}${field('Combustível (R$/litro)','price','number',r?.price??p.price,'min="0.01" step="0.001" required')}${field('Consumo médio (km/l)','eff','number',r?.eff??p.eff,'min="0.1" step="0.1" required')}</div><p class="help">Se o horário final for menor que o inicial, o término será considerado no dia seguinte.</p><div class="formsection">Reservas desta rota</div><p class="help">Use zero quando não quiser separar um valor. Os nomes continuam disponíveis nas próximas rotas.</p><div class="fields">${state.reserves.map(v=>field(esc(v.name)+' (R$)','reserve_'+v.id,'number',r?(r.reserves[v.id]||0):v.daily,'min="0" step="0.01"')).join('')}</div><button type="button" class="textbtn" id="inlineReserve">＋ Criar reserva</button><div class="formsection">Outros gastos da rota</div><p class="help">Adicione alimentação, estacionamento, pedágio ou outros gastos. Eles serão descontados do valor para as contas.</p><div id="expenseRows"></div><button type="button" class="textbtn" id="addExpense">＋ Adicionar gasto</button><div class="preview" id="routePreview"></div>`,f=>{let km=f.get('mode')==='odo'?Number(f.get('odoEnd'))-Number(f.get('odoStart')):Number(f.get('km'));if(!(km>0))throw Error('A quilometragem precisa ser maior que zero e o KM final maior que o inicial.');let start=f.get('date')+'T'+f.get('start'),end=f.get('date')+'T'+f.get('end');if(f.get('end')===f.get('start'))throw Error('Informe horários diferentes para início e fim.');if(end<start){let d=dateObj(f.get('date'));d.setDate(d.getDate()+1);end=d.toLocaleDateString('en-CA')+'T'+f.get('end')}let item={id:r?.id||uid(),date:f.get('date'),start,end,platform:f.get('platform'),mode:f.get('mode'),odoStart:Number(f.get('odoStart')),odoEnd:Number(f.get('odoEnd')),km,gross:Number(f.get('gross')),price:Number(f.get('price')),eff:Number(f.get('eff')),reserves:Object.fromEntries(state.reserves.map(v=>[v.id,Number(f.get('reserve_'+v.id)||0)])),expenses:readExpenses(),targetSnapshot:target(f.get('date'))};if(r)state.routes[state.routes.indexOf(r)]=item;else state.routes.push(item);save();$('#modal').close();day=item.date;render();toast('Rota salva. Seu resultado já foi atualizado.');});function kmFields(){let odo=$('#kmMode').value==='odo';$('#kmFields').innerHTML=odo?field('KM inicial','odoStart','number',r?.odoStart||'','min="0" step="0.1" required')+field('KM final','odoEnd','number',r?.odoEnd||'','min="0" step="0.1" required'):field('Distância rodada (km)','km','number',r?.km||'','min="0.1" step="0.1" required');preview()}function readExpenses(){return Array.from(document.querySelectorAll('.expenseRow')).map(row=>({name:row.querySelector('[data-expense-name]').value.trim(),amount:Number(row.querySelector('[data-expense-amount]').value)})).filter(e=>e.name||e.amount>0)}function addExpense(e={name:'',amount:''}){let row=document.createElement('div');row.className='expenseRow';row.innerHTML=`<input aria-label="Descrição do gasto" data-expense-name placeholder="Ex.: alimentação" maxlength="80" required value="${esc(e.name)}"><input aria-label="Valor do gasto em reais" data-expense-amount type="number" min="0.01" step="0.01" placeholder="R$" required value="${esc(e.amount)}"><button type="button" class="danger" aria-label="Remover gasto">×</button>`;row.querySelector('button').onclick=()=>{row.remove();preview()};$('#expenseRows').append(row);preview()}function preview(){let f=new FormData($('#form')),km=f.get('mode')==='odo'?Number(f.get('odoEnd'))-Number(f.get('odoStart')):Number(f.get('km')),gas=km>0&&Number(f.get('eff'))>0?km/Number(f.get('eff'))*Number(f.get('price')):0,res=state.reserves.reduce((s,v)=>s+Number(f.get('reserve_'+v.id)||0),0);let exp=readExpenses().reduce((s,e)=>s+e.amount,0);$('#routePreview').innerHTML=`Combustível estimado: <b>${money(gas)}</b> · Reservas: <b>${money(res)}</b><br>Outros gastos: <b>${money(exp)}</b><br>Disponível para contas: <b>${money(Number(f.get('gross'))-gas-res-exp)}</b>`}$('#kmMode').onchange=kmFields;$('#form').oninput=preview;$('#inlineReserve').onclick=()=>{let name=prompt('Nome da reserva (ex.: manutenção)');if(name?.trim()){let v={id:uid(),name:name.trim(),daily:0};state.reserves.push(v);save();let box=document.createElement('div');box.innerHTML=field(esc(v.name)+' (R$)','reserve_'+v.id,'number',0,'min="0" step="0.01"');$('#inlineReserve').before(box);preview()}};$('#addExpense').onclick=()=>addExpense();(r?.expenses||[]).forEach(addExpense);kmFields()}
function renderPlan(){let p=state.plan,m=planning();$('#app').innerHTML=`<div class="hero"><div><small>SEU PLANEJAMENTO EM NÚMEROS</small><h2>${money(m.gross)} <span style="font-size:13px;font-weight:400;color:#aac3e4">/ dia de trabalho</span></h2><p>${m.remainingDays.length} dias de trabalho restantes · ${money(m.base)} ainda para as contas.</p></div><div class="heroright"><div class="targetrow"><span>Contas pendentes até o prazo</span><b>${money(m.total)}</b></div><div class="targetrow"><span>Meta líquida por dia</span><b>${money(m.daily)}</b></div><div class="targetrow"><span>Combustível + reservas / dia</span><b>${money(m.gas+m.dailyReserve)}</b></div></div></div><div class="grid" style="margin-top:22px"><div class="panel"><div class="panelhead"><div><h3>Configure seu caminho</h3><p>As folgas ficam fora da divisão da meta</p></div></div><form class="planform" id="planform"><div class="fields">${field('Data inicial','start','date',p.start,'required')}${field('Data limite','end','date',p.end,'required')}${field('KM previstos por dia','km','number',p.km,'min="0" step="0.1" required')}${field('Consumo médio (km/l)','eff','number',p.eff,'min="0.1" step="0.1" required')}${field('Combustível (R$/litro)','price','number',p.price,'min="0.01" step="0.001" required')}${field('Valor separado manualmente, sem as rotas (R$)','initial','number',p.initial,'min="0" step="0.01" required')}</div><div class="preview"><b>Total separado para contas: ${money(m.separated)}</b><br>Manual: ${money(p.initial)} + líquido das rotas: ${money(m.routeCredit)} − contas pagas: ${money(m.paid)}<br><small>As rotas do período até hoje entram automaticamente, inclusive em folgas. Editar ou excluir uma rota recalcula o saldo.</small></div><div class="formsection">Dias de folga na semana</div><div class="weekdays">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map((v,i)=>`<label><input type="checkbox" name="off" value="${i}" ${p.off.includes(i)?'checked':''}> ${v}</label>`).join('')}</div><div class="formsection">Folgas em datas específicas</div>${field('Datas separadas por vírgula (AAAA-MM-DD)','dates','text',p.dates,'placeholder="2026-12-24, 2026-12-25"')}<p class="help">Meta = saldo que falta para as contas dividido pelos dias de trabalho restantes, mais combustível e reservas diárias. O líquido das rotas desconta combustível, reservas e outros gastos. O saldo manual deve conter apenas valores que não vieram das rotas cadastradas. Contas vencidas também entram. O plano distribui o total igualmente: confira vencimentos anteriores ao prazo final.</p><button class="primary" style="margin-top:12px">Atualizar planejamento</button></form></div><div><div class="panel"><div class="panelhead"><div><h3>Contas a pagar</h3><p>Valores e vencimentos no seu radar</p></div><button class="textbtn" onclick="billForm()">＋ Adicionar</button></div>${state.bills.length?state.bills.slice().sort((a,b)=>a.due.localeCompare(b.due)).map(b=>`<div class="billrow ${b.paid?'done':''}"><input type="checkbox" aria-label="Marcar conta paga" ${b.paid?'checked':''} onchange="paid('${b.id}',this.checked)"><div class="detail"><strong>${esc(b.name)}</strong><small>Vence em ${dateObj(b.due).toLocaleDateString('pt-BR')}</small></div><b>${money(b.amount)}</b><button class="textbtn" onclick="billForm('${b.id}')">✎</button><button class="danger" onclick="remove('bills','${b.id}')">×</button></div>`).join(''):'<div class="empty">Nenhuma conta cadastrada.<br>Adicione suas contas para calcular a meta.</div>'}</div><div class="panel" style="margin-top:20px"><div class="panelhead"><div><h3>Suas reservas</h3><p>Valor sugerido por dia, ajustável em cada rota</p></div><button class="textbtn" onclick="reserveForm()">＋ Criar</button></div>${state.reserves.map(r=>`<div class="reserveitem"><div><strong>${esc(r.name)}</strong><br><small>${money(r.daily)} / dia</small></div><button class="textbtn" onclick="reserveForm('${r.id}')">Editar</button><button class="danger" onclick="remove('reserves','${r.id}')">×</button></div>`).join('')||'<div class="empty">Crie reservas para manutenção, sonhos e imprevistos.</div>'}</div></div></div>`;$('#planform').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target);if(f.get('end')<f.get('start'))return toast('A data limite precisa ser igual ou posterior à inicial.');if(dates(f.get('start'),f.get('end')).length>=3660)return toast('Escolha um período menor que 10 anos.');let ds=f.get('dates');if(ds.trim()&&ds.split(',').some(d=>!/^\d{4}-\d{2}-\d{2}$/.test(d.trim())||isNaN(dateObj(d.trim()))))return toast('Confira as datas de folga: use AAAA-MM-DD.');state.plan={start:f.get('start'),end:f.get('end'),km:+f.get('km'),eff:+f.get('eff'),price:+f.get('price'),initial:+f.get('initial'),off:f.getAll('off').map(Number),dates:ds};if(!workDays().length)return toast('Selecione ao menos um dia de trabalho.');save();render();toast('Planejamento atualizado. A meta já está conectada às rotas.')}}
function billForm(id){let b=state.bills.find(x=>x.id===id);openModal(b?'Editar conta':'Nova conta',`<div class="fields"><div class="full">${field('Nome da conta','name','text',b?.name||'','required maxlength="80"')}</div>${field('Valor (R$)','amount','number',b?.amount||'','min="0.01" step="0.01" required')}${field('Vencimento','due','date',b?.due||state.plan.end,'required')}</div>`,f=>{let item={id:b?.id||uid(),name:f.get('name').trim(),amount:+f.get('amount'),due:f.get('due'),paid:b?.paid||false};if(!item.name)throw Error('Informe o nome da conta.');if(b)Object.assign(b,item);else state.bills.push(item);save();$('#modal').close();render();toast('Conta salva.')})}
function reserveForm(id){let r=state.reserves.find(x=>x.id===id);openModal(r?'Editar reserva':'Criar reserva',`<div class="fields">${field('Nome da reserva','name','text',r?.name||'','required maxlength="60"')}${field('Sugestão diária (R$)','daily','number',r?.daily??0,'min="0" step="0.01" required')}</div><p class="help">Esse valor entra no planejamento diário. Em cada rota você pode alterar ou deixar zero. Se rodar várias vezes no dia, distribua o valor entre as rotas.</p>`,f=>{let name=f.get('name').trim();if(!name)throw Error('Informe o nome da reserva.');if(r)Object.assign(r,{name,daily:+f.get('daily')});else state.reserves.push({id:uid(),name,daily:+f.get('daily')});save();$('#modal').close();render();toast('Reserva salva.')})}
function paid(id,v){state.bills.find(x=>x.id===id).paid=v;save();render()}function remove(collection,id){if(confirm('Excluir este registro?')){state[collection]=state[collection].filter(x=>x.id!==id);save();render()}}
function reportRange(){let d=dateObj(reportDay),a,b;if(period==='day')a=b=reportDay;if(period==='week'){d.setDate(d.getDate()-((d.getDay()+6)%7));a=d.toLocaleDateString('en-CA');d.setDate(d.getDate()+6);b=d.toLocaleDateString('en-CA')}if(period==='month'){a=reportDay.slice(0,7)+'-01';d=new Date(d.getFullYear(),d.getMonth()+1,0,12);b=d.toLocaleDateString('en-CA')}return [a,b]}
function renderReports(){let [a,b]=reportRange(),rs=state.routes.filter(r=>r.date>=a&&r.date<=b),t=totals(rs),goal=dates(a,b).reduce((s,d)=>s+target(d),0),days=dates(a,b);$('#app').innerHTML=`<div class="datebar"><strong>${dateObj(a).toLocaleDateString('pt-BR')} — ${dateObj(b).toLocaleDateString('pt-BR')}</strong><div class="reportcontrols"><select id="period" aria-label="Período do relatório">${[['day','Diário'],['week','Semanal'],['month','Mensal']].map(([v,l])=>`<option value="${v}" ${period===v?'selected':''}>${l}</option>`).join('')}</select><input type="date" id="reportDate" aria-label="Data de referência" value="${reportDay}"></div></div><div class="hero"><div><small>SEU RESULTADO NO PERÍODO</small><h2>${money(t.gross)}</h2><p>${rs.length} rotas registradas · ${num(t.km)} km percorridos</p></div><div class="heroright"><div class="targetrow"><span>Meta planejada no período</span><b>${money(goal)}</b></div><div class="targetrow"><span>${t.gross>=goal?'Além da meta':'Falta para a meta'}</span><b>${money(Math.abs(t.gross-goal))}</b></div><div class="targetrow"><span>Ganho líquido por hora</span><b>${money(t.hours?t.net/t.hours:0)}</b></div></div></div>${stats(t)}<div class="grid"><div class="panel"><div class="panelhead"><div><h3>Seu ritmo de conquistas</h3><p>Faturamento bruto por dia</p></div><button class="textbtn" id="csv">↓ Exportar CSV</button></div><div class="chart">${days.map(d=>{let v=totals(rs.filter(r=>r.date===d)).gross,max=Math.max(1,...days.map(x=>totals(rs.filter(r=>r.date===x)).gross));return `<div class="chartcol" title="${d}: ${money(v)}"><i style="height:${v/max*110}px"></i><small>${d.slice(8)}</small></div>`}).join('')}</div>${routeTable(rs)}</div>${allocation(t)}</div><div class="bottomnote"><span>◈</span><span>As médias são ponderadas: total recebido dividido pelas horas ou quilômetros do período. Líquido por km: <b>${money(t.km?t.net/t.km:0)}</b>. A meta do relatório usa o planejamento atual.</span></div>`;$('#period').onchange=e=>{period=e.target.value;render()};$('#reportDate').onchange=e=>{reportDay=e.target.value||today();render()};$('#csv').onclick=()=>download('rotago-relatorio.csv','\uFEFFData;Plataforma;Inicio;Fim;KM;Recebido;Combustivel;Reservas;Outros gastos;Para contas\n'+rs.map(r=>[r.date,r.platform,r.start,r.end,r.km,r.gross,fuel(r).toFixed(2),reserved(r).toFixed(2),extras(r).toFixed(2),net(r).toFixed(2)].join(';')).join('\n'),'text/csv')}
function switchTab(t){tab=t;render();window.scrollTo({top:0,behavior:'smooth'})}function download(name,content,type){let a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>switchTab(b.dataset.tab));$('#topaction').onclick=()=>tab==='plan'?billForm():routeForm();$('#close').onclick=()=>$('#modal').close();$('#theme').onclick=()=>{state.theme=state.theme==='dark'?'light':'dark';save();render()};$('#backup').onclick=()=>download('rotago-backup-'+today()+'.json',JSON.stringify(state,null,2),'application/json');$('#restore').onchange=async e=>{try{let x=JSON.parse(await e.target.files[0].text());if(!x.plan||!Array.isArray(x.bills)||!Array.isArray(x.reserves)||!Array.isArray(x.routes)||!Array.isArray(x.plan.off)||!Number.isFinite(x.plan.eff)||x.plan.eff<=0||!/^\d{4}-\d{2}-\d{2}$/.test(x.plan.start)||!/^\d{4}-\d{2}-\d{2}$/.test(x.plan.end))throw Error();for(let r of x.routes)if((r.expenses!==undefined&&(!Array.isArray(r.expenses)||r.expenses.some(e=>typeof e.name!=='string'||!Number.isFinite(e.amount)||e.amount<0)))||!(r.eff>0)||!(r.km>0)||!Number.isFinite(r.gross)||!r.reserves||!(hours(r)>0))throw Error();if(confirm('Restaurar este backup e substituir os dados atuais?')){state=x;save();render();toast('Backup restaurado.')}}catch{toast('Arquivo inválido. Escolha um backup do RotaGo.')}e.target.value=''};render();
